import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync, writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at = file => fileURLToPath(new URL(file, import.meta.url));
const fn = '_M0FP210JingLan0v03stn13relax_2einner';
for (const driver of ['lookupbench', 'deepbench']) {
  const original = readFileSync(at('base-' + driver + '.js'), 'utf8').replaceAll('\r\n', '\n');
  const start = original.indexOf('function ' + fn + '(');
  const end = original.indexOf('\nfunction ', start + 1);
  assert(start >= 0 && end > start);
  const body = original.slice(start, end);
  const marker = '      changed = -1;\n      const _bind =';
  assert.equal(body.split(marker).length, 2);
  const counters = body.replace(marker, '      stats.passes++;\n      stats.visits += arcs.length;\n' + marker);
  for (const mode of ['counts', 'timer']) {
    const wrap = 'const stats = {calls:0,passes:0,visits:0,ms:0,rounds:{}};\n' +
      'const saved = ' + fn + ';\n' + fn + ' = (n, arcs, budget, numeric) => {\n' +
      '  assertPlanning(numeric);\n  stats.calls++;\n' + (mode === 'counts' ?
      '  const passes=stats.passes;\n  const result=saved(n,arcs,budget,numeric);\n' +
      '  const rounds=stats.passes-passes;\n  stats.rounds[rounds]=(stats.rounds[rounds]??0)+1;\n  return result;\n' :
      '  const start=performance.now();\n  try {return saved(n,arcs,budget,numeric);}\n  finally {stats.ms+=performance.now()-start;}\n') +
      '};\nfunction assertPlanning(numeric){if(numeric)throw new Error("unexpected numeric solver");}\n' +
      "process.once('exit', () => console.error(JSON.stringify(stats)));\n";
    const code = mode === 'counts' ? original.slice(0, start) + counters + original.slice(end) : original;
    writeFileSync(at('base-' + driver + '-' + mode + '.js'), wrap + code);
  }
}
const cases = ['maintenance', 'independent', 'distinct-resources', 'first-pair', 'four-resources',
  'one-resource','max-root','max-model','zero-origin','tight-impossible'];
const rows = [];
for (const name of cases) {
  const deep = name === 'tight-impossible';
  const run = mode => {
    const driver = at('base-' + (deep ? 'deepbench' : 'lookupbench') + '-' + mode + '.js');
    const r = spawnSync(process.execPath, deep ? [driver] : [driver,name], {encoding:'utf8',timeout:40000});
    assert.ifError(r.error);
    assert.equal(r.status, 0, r.stderr);
    const samples = r.stdout.trim().split(/\r?\n/);
    assert.equal(samples.length,9);
    const probe = JSON.parse(r.stderr);
    return mode === 'counts' ? {calls:probe.calls,passes:probe.passes,visits:probe.visits,rounds:probe.rounds}
      : {calls:probe.calls, ms:probe.ms};
  };
  const counts = run('counts');
  const phase = Array.from({length:3}, () => run('timer'));
  assert(phase.every(p => p.calls === counts.calls));
  assert.equal(Object.entries(counts.rounds).reduce((s,[rounds,calls])=>s+Number(rounds)*calls,0), counts.passes);
  rows.push({name,counts,phase});
  console.log(name, counts.calls, counts.passes, counts.visits, ...phase.map(p=>p.ms.toFixed(2)));
}
writeFileSync(at('baseline-probe.json'), JSON.stringify(rows,null,2)+'\n');

